using NUnit.Framework;

namespace Depths.Tests
{
    /// <summary>
    /// Shooters and gunners against the running game. Every row was recorded by tools/ranged-parity.js
    /// on 2026-10-06 from the game's own tickBodies(): seed 4242, the player held still with a fixed
    /// velocity and swerve, Rnd reseeded before the first tick, every 10th tick compared to 1e-6
    /// (position, castT, castReady, shootCd, castAim, dodgeCd, knock velocity; then the shells fired
    /// and the player's hp), jitter draws exact. Covers the standoff walk, the cast, the intercept lead
    /// against a moving, swerving player, the aim sweep around a lunger in the line, and the gunner dodge.
    /// </summary>
    [TestFixture]
    public sealed class RangedParityTests
    {
        static void Check(double[] player, (BodyKind kind, double x, double y, double shootCd, int idleTimer)[] bodies,
                          double[]? shell, int ticks, int jitterDraws, object[][] rows)
        {
            var run = new RunState(new Rng(4242)) { dungeon = Dungeon.FromSeed(new Rng(4242)) };
            run.state = "playing";
            var p = run.player;
            p.x = p.lagX = player[0]; p.y = p.lagY = player[1]; p.vx = player[2]; p.vy = player[3]; p.swerve = player[4];
            p.hp = p.maxHp = 1e6;
            TickOrder.HitboxX = p.lagX; TickOrder.HitboxY = p.lagY;
            for (int i = 0; i < bodies.Length; i++)
            {
                var b = bodies[i];
                var e = Enemy.Of(b.kind, b.x, b.y);
                e.noticeTimer = 0; e.aggroTimer = 0; e.flank = i * 2.399963229728653;
                e.shootCd = b.shootCd; e.idleTimer = b.idleTimer;
                run.enemies.Add(e);
            }
            if (shell != null)
                run.projectiles.Add(new Projectile { x = shell[0], y = shell[1], vx = shell[2], vy = shell[3], r = 5, dmg = 1, friendly = true, scale = 1, dx = 1 });
            int j0 = run.rng.JitterCalls, r0 = run.rng.RunCalls, row = 0;
            for (int t = 1; t <= ticks; t++)
            {
                p.iframes = 0;
                TickOrder.TickBodies(run);
                if (t % 10 != 0) continue;
                var want = rows[row++];
                Assert.That(t, Is.EqualTo(System.Convert.ToInt32(want[0])));
                for (int i = 0; i < run.enemies.Count; i++)
                {
                    var e = run.enemies[i];
                    int o = 1 + i * 9;
                    string at = " (body " + i + ", tick " + t + ")";
                    double D(int k) => System.Convert.ToDouble(want[o + k]);
                    Assert.That(e.x, Is.EqualTo(D(0)).Within(1e-6), "x" + at);
                    Assert.That(e.y, Is.EqualTo(D(1)).Within(1e-6), "y" + at);
                    if (e.kind != BodyKind.Lunger)
                    {
                        Assert.That(e.castT, Is.EqualTo((int)D(2)), "castT" + at);
                        Assert.That(e.castReady, Is.EqualTo((bool)want[o + 3]), "castReady" + at);
                        Assert.That(e.shootCd, Is.EqualTo(D(4)).Within(1e-6), "shootCd" + at);
                        Assert.That(e.castAim, Is.EqualTo(D(5)).Within(1e-6), "castAim" + at);
                        Assert.That(e.dodgeCd, Is.EqualTo((int)D(6)), "dodgeCd" + at);
                    }
                    Assert.That(e.kvx, Is.EqualTo(D(7)).Within(1e-6), "kvx" + at);
                    Assert.That(e.kvy, Is.EqualTo(D(8)).Within(1e-6), "kvy" + at);
                }
                int n = 1 + run.enemies.Count * 9;
                Assert.That(run.projectiles.Count, Is.EqualTo(System.Convert.ToInt32(want[n])), "shells at tick " + t);
                Assert.That(p.hp, Is.EqualTo(System.Convert.ToDouble(want[n + 1])).Within(1e-6), "player hp at tick " + t);
            }
            Assert.That(run.rng.JitterCalls - j0, Is.EqualTo(jitterDraws), "jitter draws");
            Assert.That(run.rng.RunCalls - r0, Is.Zero, "the body phase drew from the run stream");
        }

